744	// handleListServices serves the read-only service overview. It aggregates the
745	// current SQLite records of every service at the requested evaluation point
746	// without creating, updating or deleting anything, and in particular without
747	// running the discovery lost-record cleanup. Lost instances stay stored and
748	// are only counted as lost.
749	func (s *Server) handleListServices(c *gin.Context) {
750		bag, apiErr := buildParamBag(c)
751		if apiErr != nil {
752			writeError(c, apiErr)
753			return
754		}
755		evaluateValue, ok := bag.get(evaluateAtKeys)
756		if !ok {
757			writeError(c, errInvalidParameter("evaluate_at is required"))
758			return
759		}
760		evaluateAt, ok := parseTimeValue(evaluateValue)
761		if !ok {
762			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
763			return
764		}
765		timeoutValue, ok := bag.get(timeoutKeys)
766		if !ok {
767			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
768			return
769		}
770		timeout, ok := parseTimeout(timeoutValue)
771		if !ok || timeout <= 0 {
772			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
773			return
774		}
775	
776		instances, err := s.store.ListAllInstances()
777		if err != nil {
778			writeError(c, errStorageUnavailable())
779			return
780		}
781		for _, instance := range instances {
782			if evaluateAt.Before(instance.HeartbeatAt) {
783				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
784				return
785			}
786		}
787	
788		// Aggregate records per service. The same counters classify every
789		// record exactly once, so total_instances is always the sum of the
790		// three state counters.
791		byService := make(map[string]*serviceCounters)
792		for _, instance := range instances {
793			counters := byService[instance.ServiceName]
794			if counters == nil {
795				counters = &serviceCounters{}
796				byService[instance.ServiceName] = counters
797			}
798			counters.total++
799			switch {
800			case evaluateAt.After(instance.HeartbeatAt.Add(timeout)):
801				counters.lost++
802			case instance.Healthy:
803				counters.available++
804			default:
805				counters.unhealthyFresh++
806			}
807		}
808	
809		serviceNames := make([]string, 0, len(byService))
810		for serviceName := range byService {
811			serviceNames = append(serviceNames, serviceName)
812		}
813		sort.Strings(serviceNames)
814	
815		services := make([]gin.H, 0, len(serviceNames))
816		for _, serviceName := range serviceNames {
817			counters := byService[serviceName]
818			services = append(services, gin.H{
819				"service_name":              serviceName,
820				"total_instances":           counters.total,
821				"available_instances":       counters.available,
822				"unhealthy_fresh_instances": counters.unhealthyFresh,
823				"lost_instances":            counters.lost,
824			})
825		}
826		c.JSON(200, gin.H{"services": services})
827	}
828	
829	type serviceCounters struct {
830		total          int
831		available      int
832		unhealthyFresh int
833		lost           int
834	}
