920	// handleBatchDiscover implements POST /api/v1/discover/batch. Several
921	// services share one evaluation point and timeout. Parameters and stored
922	// data are fully validated before any record is removed: every specified
923	// service is read first, the clock-skew guard covers every instance of
924	// every specified service, and lost records across all services are removed
925	// in one transaction so a failure never leaves partial deletions. Services
926	// that are not requested are never read or touched; a requested service
927	// without records yields an empty instance list while keeping its place in
928	// the request order.
929	func (s *Server) handleBatchDiscover(c *gin.Context) {
930		body, apiErr := readJSONObject(c)
931		if apiErr != nil {
932			writeError(c, apiErr)
